<?php
// ===== Läs-API (v1): token-autentisering och hjälpfunktioner =====
function api_tokens_ok(){ try{ db()->query('SELECT 1 FROM api_tokens LIMIT 0'); return true; }catch(Throwable $e){ return false; } }
function api_hash($t){ return hash('sha256',(string)$t); }
function api_new_token($name,$uid){ $t='vmm_'.bin2hex(random_bytes(20)); db()->prepare('INSERT INTO api_tokens(name,prefix,token_hash,created_by) VALUES(?,?,?,?)')->execute([mb_substr(trim($name)?:'token',0,80),substr($t,0,8),api_hash($t),$uid]); return $t; }
function api_token_from_request(){ $h=(string)($_SERVER['HTTP_AUTHORIZATION']??$_SERVER['REDIRECT_HTTP_AUTHORIZATION']??''); if(preg_match('/^Bearer\s+(\S+)/i',$h,$m)) return $m[1];
 if(preg_match('/^Basic\s+(\S+)/i',$h,$m)){ $b=base64_decode($m[1]); if($b!==false&&strpos($b,':')!==false){ [$u,$p]=explode(':',$b,2); return $p!==''?$p:$u; } }
 foreach(['HTTP_X_API_KEY'] as $k) if(!empty($_SERVER[$k])) return (string)$_SERVER[$k];
 return (string)($_GET['token']??''); }
function api_auth(){ $t=api_token_from_request(); $ok=false;
 if($t!==''&&api_tokens_ok()){ $q=db()->prepare('SELECT id,last_used FROM api_tokens WHERE token_hash=? AND enabled=1'); $q->execute([api_hash($t)]); $r=$q->fetch(); if($r){ $ok=true; if($r['last_used']===null||strtotime($r['last_used'])<time()-60) db()->prepare('UPDATE api_tokens SET last_used=NOW(),last_ip=? WHERE id=?')->execute([substr(client_ip(),0,45),$r['id']]); } }
 if(!$ok){ usleep(400000); applog('warning','api','API authentication failed from '.client_ip()); http_response_code(401); header('WWW-Authenticate: Bearer realm="vmmon"'); header('Content-Type: application/json'); echo json_encode(['error'=>'unauthorized','message'=>'Missing or invalid API token']); exit; } }
function api_json($d,$code=200){ http_response_code($code); header('Content-Type: application/json; charset=utf-8'); header('Cache-Control: no-store'); echo json_encode($d,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_PARTIAL_OUTPUT_ON_ERROR); exit; }
function api_err($code,$msg){ api_json(['error'=>$code>=500?'server_error':'bad_request','message'=>$msg],$code); }
function api_time($v,$def){ if($v===null||$v==='') return $def; if(preg_match('/^-(\d+)\s*([smhdw])$/',trim((string)$v),$m)) return time()-(int)$m[1]*['s'=>1,'m'=>60,'h'=>3600,'d'=>86400,'w'=>604800][$m[2]]; if(is_numeric($v)){ $n=(float)$v; return (int)($n>1e11?$n/1000:$n); } $x=strtotime((string)$v); return $x?:$def; }
function api_cat_name($s){ return ['svc'=>'services','hv'=>'virtualization','nw'=>'network','st'=>'storage','bmc'=>'bmc','srv'=>'server'][dev_cat($s)]; }
// Sammanfattning av en enhet (samma uppgifter oavsett typ)
function api_device($s,$cs,$groups=[]){ $c=dev_cat($s); $cpu=$mem=null; $disks=[]; $up=null; $ping=null; $extra=[];
 foreach($cs as $k){ if($k['kind']==='ping'&&in_array($k['source'],['tcp','zabbix'],true)&&(int)($k['enabled']??1)){ $ping=$k['last_status']; } }
 if($c==='svc'){ $up=null; }
 elseif($c==='hv'){ $d=json_decode((string)$s['hv_data'],true)?:[]; $cpu=$d['cpu']??null; $mem=$d['mem']??null; foreach($d['storage']??[] as $x) if(!empty($x['total'])) $disks[]=['name'=>$x['n'],'used_pct'=>round($x['used']/$x['total']*100,1),'total_bytes'=>$x['total']];
  $up=$s['hv_status']?($s['hv_status']==='up'):($ping?$ping==='up':null); $extra=['type'=>$s['hv_type'],'version'=>$d['version']??null,'vms'=>count($d['vms']??[]),'vms_running'=>count(array_filter($d['vms']??[],fn($v)=>in_array($v['state']??'',['running','poweredon'],true)))]; }
 elseif($c==='srv'){ $m=srv_metrics($cs); $cpu=$m['cpu']; $mem=$m['mem']; foreach($m['disks'] as $x) if($x['t']>0) $disks[]=['name'=>$x['n'],'used_pct'=>round(100-$x['f']/$x['t']*100,1),'total_bytes'=>$x['t']]; $up=$ping?$ping==='up':null; if($up===null){ foreach($cs as $k) if($k['last_check']!==null){ $up=true; break; } } }
 else{ $d=json_decode((string)$s['nw_data'],true)?:[]; $cpu=$d['cpu']??null; $mem=$d['mem']??null; if($c==='st'||in_array($s['nw_role']??'',['firewall','cloudkey'],true)) foreach($d['disks']??[] as $x) if(($x['t']??0)>0) $disks[]=['name'=>$x['n'],'used_pct'=>round(100-$x['f']/$x['t']*100,1),'total_bytes'=>$x['t']];
  $up=$s['nw_status']?($s['nw_status']==='up'):($ping?$ping==='up':null); $extra=['vendor'=>$s['nw_type'],'role'=>$s['nw_role'],'model'=>$d['model']??null,'temperature_c'=>$d['temp']??null,'uptime_s'=>$d['uptime']??null]; }
 $o=['id'=>(int)$s['id'],'name'=>$s['name'],'host'=>$s['host'],'category'=>api_cat_name($s),'enabled'=>(bool)$s['enabled'],'maintenance'=>!empty($s['maint']),'up'=>$up,'ping'=>$ping,'cpu_pct'=>$cpu===null?null:round((float)$cpu,1),'memory_pct'=>$mem===null?null:round((float)$mem,1),'disks'=>$disks,'groups'=>$groups];
 return $extra?$o+['details'=>$extra]:$o; }
function api_groups_map(){ $m=[]; try{ foreach(db()->query('SELECT g.name,m.server_id FROM device_group_members m JOIN device_groups g ON g.id=m.group_id ORDER BY g.sort,g.name') as $r) $m[(int)$r['server_id']][]=$r['name']; }catch(Throwable $e){} return $m; }
function api_servers($id=0){ $q=db()->prepare('SELECT *,(maint_until IS NOT NULL AND maint_until>NOW()) AS maint FROM servers'.($id?' WHERE id=?':'').' ORDER BY name'); $q->execute($id?[$id]:[]); return $q->fetchAll(); }
function api_checks_by_server(){ $m=[]; foreach(db()->query('SELECT * FROM server_checks ORDER BY server_id,'.chk_ord()) as $c) $m[(int)$c['server_id']][]=$c; return $m; }
function api_check_row($c,$s=null){ return ['id'=>(int)$c['id'],'device_id'=>(int)$c['server_id'],'device'=>$s['name']??null,'label'=>$c['label'],'source'=>$c['source'],'kind'=>$c['kind'],'enabled'=>(bool)$c['enabled'],'up'=>$c['last_status']===null?null:$c['last_status']==='up','detail'=>$c['last_detail'],'value'=>$c['last_value']===null?null:(float)$c['last_value'],'last_check'=>$c['last_check']?date('c',strtotime($c['last_check'])):null]; }
function api_iface_row($i,$s=null){ return ['device_id'=>(int)$i['server_id'],'device'=>$s['name']??null,'index'=>(int)$i['if_index'],'name'=>$i['name'],'alias'=>$i['alias'],'speed_mbps'=>(int)$i['speed_mbps'],'admin_up'=>(int)$i['admin']===1,'up'=>(int)$i['oper']===1,'in_bps'=>$i['rate_in']===null?null:(float)$i['rate_in'],'out_bps'=>$i['rate_out']===null?null:(float)$i['rate_out'],'errors_per_min'=>$i['err_pm']===null?null:(float)$i['err_pm'],'discards_per_min'=>$i['disc_pm']===null?null:(float)$i['disc_pm'],'crc_errors_per_min'=>!isset($i['crc_pm'])||$i['crc_pm']===null?null:(float)$i['crc_pm'],'ips'=>$i['ips']]; }
function api_firing(){ return db()->query("SELECT a.rule_id,a.server_id,a.since,r.metric,r.threshold,s.name server FROM alert_state a JOIN alert_rules r ON r.id=a.rule_id JOIN servers s ON s.id=a.server_id WHERE a.firing=1 ORDER BY a.since")->fetchAll(); }
function prom_esc($v){ return str_replace(['\\','"',"\n"],['\\\\','\\"','\\n'],(string)$v); }
function prom_line(&$o,$name,$labels,$val){ if($val===null) return; $l=''; foreach($labels as $k=>$v) $l.=($l===''?'':',').$k.'="'.prom_esc($v).'"'; $o[$name][]=$name.($l!==''?'{'.$l.'}':'').' '.(is_bool($val)?(int)$val:(is_float($val)?rtrim(rtrim(sprintf('%.6F',$val),'0'),'.'):$val)); }
function api_prometheus(){ $o=[]; $help=['vmmon_device_up'=>'Device reachable (1/0)','vmmon_device_cpu_percent'=>'CPU usage percent','vmmon_device_memory_percent'=>'Memory usage percent','vmmon_device_temperature_celsius'=>'Device temperature','vmmon_disk_used_percent'=>'Disk/volume/storage used percent','vmmon_check_up'=>'Check status (1 up, 0 down)','vmmon_check_value'=>'Last numeric value of a check (e.g. response ms)','vmmon_interface_up'=>'Interface operational status','vmmon_interface_in_bits_per_second'=>'Interface inbound rate','vmmon_interface_out_bits_per_second'=>'Interface outbound rate','vmmon_interface_errors_per_minute'=>'Interface errors per minute','vmmon_interface_discards_per_minute'=>'Interface discards per minute','vmmon_vm_running'=>'VM running (1/0)','vmmon_vm_cpu_percent'=>'VM CPU percent','vmmon_vm_memory_percent'=>'VM memory percent','vmmon_alert_firing'=>'Alert rule currently firing','vmmon_alerts_firing_total'=>'Number of firing alerts'];
 $cks=api_checks_by_server(); $grp=api_groups_map(); $GM=guest_mem_map();
 foreach(api_servers() as $s){ $id=(int)$s['id']; if(!$s['enabled']) continue; $d=api_device($s,$cks[$id]??[],$grp[$id]??[]); $L=['device'=>$s['name'],'category'=>$d['category']];
  if($d['category']!=='services'){ prom_line($o,'vmmon_device_up',$L,$d['up']); prom_line($o,'vmmon_device_cpu_percent',$L,$d['cpu_pct']); prom_line($o,'vmmon_device_memory_percent',$L,$d['memory_pct']); prom_line($o,'vmmon_device_temperature_celsius',$L,isset($d['details']['temperature_c'])?(float)$d['details']['temperature_c']:null); }
  foreach($d['disks'] as $k) prom_line($o,'vmmon_disk_used_percent',$L+['disk'=>$k['name']],(float)$k['used_pct']);
  if(dev_cat($s)==='hv'){ $hd=json_decode((string)$s['hv_data'],true)?:[]; foreach($hd['vms']??[] as $v){ $VL=['host'=>$s['name'],'vm'=>$v['n']]; prom_line($o,'vmmon_vm_running',$VL,in_array($v['state']??'',['running','poweredon'],true)?1:0); if(isset($v['cpu'])) prom_line($o,'vmmon_vm_cpu_percent',$VL,round((float)$v['cpu'],1)); $mu=$GM[strtolower($v['n'])]??((($v['mem_t']??0)>0&&isset($v['mem']))?$v['mem']/$v['mem_t']*100:null); if($mu!==null) prom_line($o,'vmmon_vm_memory_percent',$VL,round((float)$mu,1)); } }
  foreach($cks[$id]??[] as $c){ if(!(int)$c['enabled']||$c['last_status']===null) continue; $CL=['device'=>$s['name'],'check'=>$c['label'],'source'=>$c['source'],'kind'=>$c['kind']]; prom_line($o,'vmmon_check_up',$CL,$c['last_status']==='up'?1:0); if($c['last_status']==='up'&&!empty($c['mon_ms'])&&preg_match('/(\d+(?:\.\d+)?)\s*ms/',(string)$c['last_detail'],$mm)) prom_line($o,'vmmon_check_value',$CL+['unit'=>'ms'],(float)$mm[1]); } }
 $sn=[]; foreach(api_servers() as $s) $sn[$s['id']]=$s; foreach(db()->query('SELECT * FROM net_if ORDER BY server_id,if_index') as $i){ $s=$sn[$i['server_id']]??null; if(!$s||!$s['enabled']) continue; $IL=['device'=>$s['name'],'interface'=>$i['name']]; prom_line($o,'vmmon_interface_up',$IL,(int)$i['oper']===1?1:0); prom_line($o,'vmmon_interface_in_bits_per_second',$IL,$i['rate_in']===null?null:(float)$i['rate_in']); prom_line($o,'vmmon_interface_out_bits_per_second',$IL,$i['rate_out']===null?null:(float)$i['rate_out']); prom_line($o,'vmmon_interface_errors_per_minute',$IL,$i['err_pm']===null?null:(float)$i['err_pm']); prom_line($o,'vmmon_interface_discards_per_minute',$IL,$i['disc_pm']===null?null:(float)$i['disc_pm']); }
 $fr=api_firing(); foreach($fr as $f) prom_line($o,'vmmon_alert_firing',['rule'=>metric_label($f['metric']),'rule_id'=>$f['rule_id'],'device'=>$f['server']],1); prom_line($o,'vmmon_alerts_firing_total',[],count($fr));
 $out=''; foreach($o as $n=>$ls){ $out.='# HELP '.$n.' '.($help[$n]??$n)."\n# TYPE ".$n." gauge\n".implode("\n",$ls)."\n"; } return $out; }
